(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ha"] = {"ui":{"skip":"Tsallake zuwa abubuwan shafin","back":"← Koma zuwa AI-gile","lang.button":"Harshe: {name}","lang.dialog":"Zaɓi harshe","lang.search":"Nemi harsuna","lang.none":"Babu harshen da ya dace","lang.notYet":"Ba a fassara {name} ba tukuna","theme.aria":"Canza yanayi: haske, duhu ko baƙi","theme.toLight":"Koma yanayin haske","theme.toDark":"Koma yanayin duhu","theme.toBlack":"Koma yanayin baƙi (baƙi na gaske, mai sauƙi ga allon OLED)","words.underline":"Ja layi a ƙarƙashin waɗannan kalmomi a shafin","words.underlineHelp":"Ku kai linzami kan kalma mai ɗigo ko ku taɓa ta don ganin ma'anarta.","words.col.todo":"Katunan da aka zaɓa don yanzu: ƙungiya za ta fara da waɗannan a gaba.","words.col.doing":"Wani AI yana aiki a kan wannan kati yanzu.","words.col.review":"Wani AI ya gama aikin; wani kuma yana duba shi kafin ya iso gare ka.","words.col.verify":"Ana jiran ka: gwada shi ka faɗa idan yana aiki.","words.col.team":"Bayananka ko amsoshinka, suna jiran ƙungiya ta ɗauka.","words.col.done":"An gama kuma an amince.","index.title":"AI-gile: ƙungiyar AI ɗinku ta masu shirye-shirye, a allo ɗaya","index.description":"AI-gile allon kanban ne don ƙungiyoyin AI masu rubuta lamba. Suna aiki yayin da kuke barci; ku kuwa kuna samun ɗan tarin abubuwa don yanke shawara, gwadawa da karɓa.","hero.logoAlt":"Alamar allon AI-gile","hero.h1.html":"Ƙungiyar AI ɗinku ta masu shirye-shirye, a allo&nbsp;ɗaya.","hero.alpha":"🐣 Pre-alpha a rufe","hero.alphaTitle":"Na farko ne kuma ba a gama ba: na gode da gwadawa!","hero.lede":"Suna ginawa yayin da kuke barci. Kuna farkawa zuwa ɗan tarin kaɗan: 'yan tambayoyi, 'yan abubuwan gwadawa, lu'u-lu'u mai shuɗi ɗaya ko biyu. Danna, karɓa, ku koma kofi ɗinku.","dl.windows":"Manhajar Windows","dl.browser":"Gudanar da shi a browser","dl.messenger":"📱 Messenger don wayarku","dl.soon":"Nan ba da daɗewa ba","dl.notify":"🔔 Ku sanar da ni idan ya buɗe","dl.notifySmall":"Alpha ko beta","hero.secondary":"Agile, amma ƙungiyar ba ta taɓa buƙatar kofin tsaye na taro ba. (Duk da haka suna yin taron.)","pitch.h2":"AI-gile da kalmomi kamar yadda kuke so","pitch.lede":"Zaɓi tsayi, daga kalma ɗaya zuwa 144. Kowane tsayi bayaninsa ne na kansa, wanda aka rubuta don wannan girman. Ja maɓallin zamiya ko ku yi amfani da maɓallan kibiya.","pitch.rangeLabel":"Tsayi cikin kalmomi","pitch.dice":"🎲 wani sigar","pitch.words.one":"kalma {n}","pitch.words.other":"kalmomi {n}","pitch.letters.one":"harafi {n}","pitch.letters.other":"haruffa {n}","pitch.chars.one":"alama {n}","pitch.chars.other":"alamomi {n}","count.line.html.one":"kati {n} a allo yanzu","count.line.html.other":"kati {n} a allo yanzu","people.humans.html.one":"👥 mutum {n}","people.humans.html.other":"👥 mutane {n}","people.agents.html.one":"🤖 wakili {n}","people.agents.html.other":"🤖 wakilai {n}","people.working.html.one":"⚡ {n} na aiki yanzu","people.working.html.other":"⚡ {n} na aiki yanzu","pre.title":"AI-gile: ana gina wani abu","pre.description":"Ana gina wani abu a nan. Allo inda ƙungiyoyin AI ke gina abin da ka nema, kuma suna koya maka yayin da suke aiki. A yanzu pre-alpha ce a rufe tare da abokai.","pre.h1":"Ana gina wani abu a nan. 🤫","pre.line":"Allo inda ƙungiyoyin AI ke gina abin da ka nema, kuma suna koya maka yayin da suke aiki. A yanzu pre-alpha ce a rufe tare da abokai.","pre.btn":"🔔 Ku sanar da ni idan ya buɗe","pre.peek":"Bayan gilashi: ainihin allon, kai tsaye. Kowane kati layi ne mai launi.","pre.peekFake":"Bayan gilashi: haka allo yake idan ana aiki.","pre.night":"🌙 Mai tsaron dare ne ke jagoranci · 😴 mutumin yana hutawa","features.aria":"Abin da yake yi","f.pile.h":"Tari ɗaya a gare ku","f.pile.html":"<b>Gare ku</b> yana ɗauke da duk abin da ke jiran ku, a kowane aiki: tambayoyi, abubuwan gwadawa, ayyukan da mutum kaɗai zai iya yi. Layinku yana faɗin abin da ke gaba da tsawon lokacin da zai ɗauka.","f.sleep.h":"Ƙungiyoyi masu aiki yayin da kuke barci","f.sleep.p":"Kowane aiki yana da jagora da ƙungiyar wakilan AI. Ku yi sharhi a kan kati sai ƙungiyar ta farka, ta yi aikin, ta mayar da shi da matakan da gajiyayyen mutum zai iya bi.","f.tester.h":"Mai gwajin AI yana dubawa tukuna","f.tester.p":"Kafin wani abu ya zo gare ku, mai gwaji yana bin matakai a kwafin manhajar kuma yana nuna abin da ya gani, da hoton allo. Ku duba waɗanda suka yi nasara ku karɓa da danna ɗaya.","f.proof.h":"Shaida, ba alkawari ba","f.proof.p":"Kowace miƙawa tana nuna abin da ya canza: fayilolin, bambancin, hotunan allo. Ba sai kun buɗe kowace manhaja don ganin an gama ba.","f.chat.h":"Ku yi hira da jagororinku","f.chat.p":"Ginshiƙi irin na Discord: alama ɗaya ga kowane aiki, lu'u-lu'u masu shuɗi ga abin da ke buƙatar ku. Ku aika wa jagora ra'ayi; zai mayar da shi kati da shiri, tare da maɓallin ✅ Go.","f.tidy.h":"Yana tsara kansa","f.tidy.p":"Katuna masu alaƙa suna haɗuwa wuri ɗaya, ana gyara taken da suka ruɗe, kuma duba token yana sa lamba ta zama marar nauyi. Ƙarancin abubuwan da za a sauya tsakaninsu, ƙarancin tunani.","f.private.h":"Naku ne, a kwamfutarku","f.private.li1":"Allon yana aiki a injin ɗinku kuma yana amsa muku kaɗai.","f.private.li2":"DM na sirri tsakanin mutane an ɓoye su daga ƙarshe zuwa ƙarshe.","f.private.li3":"Babu asusu, babu masu bin diddigi, babu kuki.","f.lang.h":"A cikin harshenku","f.lang.p":"Harsuna sama da 120, daga Dutch, Welsh da Japananci zuwa na 'yan fashin teku, Yoda da Klingon, da saurin komawa Turanci don kalmomin sana'a.","f.service.h":"Daga ra'ayi zuwa sabis na gaske","f.service.p":"Ka gina wani abu da AI da mutane ke amfani da shi yanzu? Yi masa alama a matsayin sabis kuma allon zai taimaka maka ka gudanar da shi da kyau: binciken uptime, shafin matsayi na jama'a, matsaloli da rubutaccen bita, canje-canje da ke buƙatar Go, ajiyar tsaro da ake dubawa kowace rana. Taimako yana koya maka kowane mataki yayin da kake tafiya.","msgr.h2":"AI-gile Messenger: ƙungiyarku a aljihunku","msgr.p1":"Ku yi magana da ƙungiyarku ta AI ba tare da buɗe allo ba. Ku yi hira da jagororin ayyukanku da abokanku, ku ga matakan gwajin kati ku amsa su, duka daga wayarku.","msgr.p2":"Don haɗa ta, ku duba lambar QR a kan allonku. Karon farko? Hirar demo mai daɗi za ta nuna muku yadda komai yake.","msgr.when":"Android da farko, sannan sigar yanar gizo don wayoyi da iPhone.","msgr.who":"Jagoran aikinku","msgr.b1":"Gyaran yanayin duhu ya shirya. Kuna son matakan gwajin?","msgr.b2":"Eh, don Allah!","msgr.b3":"1. Buɗe Saiti. 2. Zaɓi Duhu. Yana da kyau kuwa?","tl.aria":"Jerin lokaci daga tattaunawar farko zuwa taswirar gaba","tl.h2":"Daga tattaunawar farko zuwa abin da ke gaba","tl.lede":"Kwanaki da lokuta na gaske, a yankin lokacinku. Bayan yau shiri ne, ba tare da alƙawarin kwanan wata ba.","tl.today":"Yau","tl.planned":"a shirye","tl.doing":"ana yi","tl.cards.one":"kati {n}","tl.cards.other":"katuna {n}","join.h2":"Ku shiga","join.lede":"Wani mutum mai gemu, ɗan baƙon hali, mai AuDHD da wasu gwagwarmaya da lafiyar ƙwaƙwalwa, tare da wakilai masu haƙuri da yawa ne ke gina AI-gile. Na sirri ne a yanzu, a alpha a rufe tare da abokai. Kuna son gwadawa idan ya buɗe?","join.btn":"Yi rijistar sha'awa","join.small":"Za mu rubuto muku imel, ba wani abu ba","footer.tag":"AI-gile. Babu masu bin diddigi, babu kuki, babu kofin tsaye na taro.","footer.licence":"Lasisin kasuwanci","footer.status":"Matsayi","footer.privacy":"Abin da muke ajiyewa","footer.thanks":"Kira albarkacin ChilledChat","form.sending":"Ana aikawa…","form.failed":"Hakan bai yi aiki ba: ku sake gwadawa daga baya.","form.offline":"Ba a iya isa ga AI-gile ba: ku sake gwadawa daga baya.","form.keep":"Muna amfani da wannan ne kawai don mu ba ku amsa, sannan mu goge shi. Babu masu bin diddigi, babu kuki.","form.keepLink":"Abin da muke ajiyewa","interest.title":"AI-gile: ku sanar da ni idan alpha ya buɗe","interest.description":"Ku bar imel ɗinku don jin lokacin da alpha ko beta na AI-gile a rufe zai buɗe.","interest.h1":"🔔 Ku sanar da ni idan ya buɗe","interest.lede":"AI-gile yana pre-alpha a rufe. Ku bar imel ɗinku za mu rubuto sau ɗaya, idan akwai wuri a gare ku.","interest.email":"Imel ɗinku","interest.which":"Wane gwaji?","interest.alpha":"Alpha a rufe: da wuri, mai tsauri, sauye-sauye da yawa","interest.beta":"Beta: ya fi tsayawa, daga baya","interest.both":"Duk ɗaya, wanda ya fara zuwa","interest.submit":"Saka ni cikin jerin","interest.thanks":"Na gode! Kuna cikin jerin.","licence.title":"AI-gile: lasisin kasuwanci","licence.description":"Kuna amfani da AI-gile a kasuwancinku? Ku nemi lasisin kasuwanci kyauta.","licence.h1":"📜 Lasisin kasuwanci","licence.lede":"Kuna amfani da AI-gile a wurin aiki? Ku gaya mana ko ku wane ne da abin da kuke yi. Idan yana yin alheri, lasisin kyauta ne.","licence.company":"Kamfani","licence.website":"Shafin yanar gizo","licence.what":"Abin da kuke yi","licence.how":"Yadda yake taimakon duniya","licence.email":"Imel","licence.submit":"Nema","licence.thanks":"Na gode! Za mu amsa ta imel.","status.title":"Matsayin AI-gile","status.h1":"Matsayin AI-gile","status.quiet":"Komai lafiya","status.intro":"Shin AI-gile yana aiki yanzu? Wannan shafi yana duba gidan yanar gizo, raba allo, kira da saukarwa duk bayan minti 5.","status.up":"Yana aiki (ya amsa cikin {ms} ms)","status.slow":"Bai amsa dubawar ƙarshe ba, ana sake gwadawa","status.down":"Ya faɗi: bai amsa dubawa biyu na ƙarshe ba","status.svc.web":"Gidan yanar gizo","status.svc.web.offers":"Wannan shafin: menene AI-gile, da fom ɗin sha'awa","status.svc.boards":"Raba allo","status.svc.boards.offers":"Alluna na jama'a, saƙonni tsakanin abokai da gayyata","status.svc.calls":"Kira","status.svc.calls.offers":"Murya, bidiyo da raba fuskar na'ura a AI-gile","status.svc.download":"Saukarwa","status.svc.download.offers":"Mai shigarwa na Windows da hanyoyin gayyata","status.checking":"Ana dubawa…","status.offline":"Ba a iya isa ga sabis ɗin matsayi yanzu (ana sake gwadawa)","status.updated":"an sabunta {ago}","status.justNow":"yanzu-yanzu","status.min":"mintuna {n} da suka wuce","status.hours":"awa {n} da ta wuce","status.days":"kwana {n} da suka wuce","privacy.title":"AI-gile: abin da muke ajiyewa","privacy.h1":"Abin da muke ajiyewa","privacy.lede":"A taƙaice: abin da kuka aiko mana kawai, kuma ba na dogon lokaci ba.","privacy.only":"Abin da kuka aiko mana kawai: abin da kuka rubuta a fom, kamar imel ɗinku. Babu wani abu kuma game da ku.","privacy.sealed":"Ana rufe shi da hatimi don kada sabarmu ta iya karanta shi: a cikin browser ɗinku kafin ya tafi (a tsohon browser, a lokacin da ya iso). Allonmu kaɗai ne zai iya buɗe shi.","privacy.server":"Ana goge shi daga sabar da zarar ya isa allonmu. Duk abin da ya rage a can bayan kwana 30 ana goge shi ko ta yaya.","privacy.board":"Muna ajiye shi a allonmu ne kawai har sai mun ba ku amsa, sannan mu goge shi a can ma.","privacy.none":"Babu masu bin diddigi, babu kuki, babu nazarin bayanai.","privacy.local":"Harshenku da zaɓinku na haske ko duhu suna zama a cikin browser ɗinku. Ba a taɓa aiko mana da su ba.","privacy.ask":"Kuna so a goge shi da wuri? Ku amsa imel ɗinmu ku faɗa mana.","live.h2":"Kalli yadda ake gina shi, kai tsaye","live.caption":"An ɓoye kowane kati: kana ganin siffar aikin, ba kalmomin ba.","live.watching.one":"kai tsaye: {n} na kallo","live.watching.other":"kai tsaye: {n} na kallo","live.last.now":"An motsa katin ƙarshe yanzu-yanzu","live.last.min.one":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.min.other":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.hour.one":"An motsa katin ƙarshe awa {n} da ta wuce","live.last.hour.other":"An motsa katin ƙarshe awanni {n} da suka wuce","live.last.day.one":"An motsa katin ƙarshe rana {n} da ta wuce","live.last.day.other":"An motsa katin ƙarshe kwanaki {n} da suka wuce","live.offline":"Allon kai tsaye yana hutawa kaɗan. Ka sake dubawa nan ba da jimawa ba.","live.cols":"Backlog|A yi|Ana yi|Ƙungiya na dubawa|Don a gwada|Don ƙungiya|An gama"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Mutummutumai.","Wakilta."]},{"n":2,"texts":["Mutummutumi kanban.","Wakilai tsararru.","Ra'ayoyi, gini."]},{"n":3,"texts":["Kanban don mutummutumai.","Ra'ayoyi su zama fasali.","Kanban na wakilai, kyauta."]},{"n":5,"texts":["Allon kanban da wakilai ke tafiyarwa.","Ku rubuta kati. Wakilai su gina.","Kyauta, na gida, ɗan wasa."]},{"n":8,"texts":["Allon kanban kyauta inda wakilan AI ke aiki.","Rubuta ra'ayi. Wakilai su gina shi. Ku karɓa.","Agile don mutum ɗaya da mutummutumai masu haƙuri da yawa."]},{"n":13,"texts":["Allon kanban a kwamfutarku inda wakilan AI ke ɗaukar katunan aiki.","Rubuta ra'ayi. Ƙungiyar wakilai ta gina shi. Mai gwaji ya duba.","Kyauta, babu asusu ko masu bin diddigi: allo, wasu mutummutumai, kuma ku ne shugaba."]},{"n":21,"texts":["AI-gile allon kanban ne don aiki da wakilan AI masu rubuta lamba. Su ke ɗaukar katunan; ku kuwa kuna gwadawa da karɓa.","Kowane aiki yana samun jagora da ƙungiyar wakilan AI. Ku yi sharhi a kowane kati sai ƙungiyar ta fara aiki.","Allon ayyuka na kai, kyauta, mai aiki a kwamfutarku. Ma'aikata mutummutumai ne. Wanda ke cewa eh, ku ne."]},{"n":34,"texts":["Kuna sa ra'ayoyi a allo. Ƙungiyar wakilan AI tana mayar da su fasalolin da ke aiki, tana gwada su, ta mayar muku da su tare da matakan gwadawa. Babu abin da ake ƙirgawa an gama sai kun faɗa.","AI-gile allon kanban ne na gida da Rich ya gina da taimako mai yawa daga wakilan da yake gudanarwa yanzu. Kyauta ne, yana aiki a kwamfutarku, ana raba shi da abokai, ba a sayarwa ba.","Ku yi tunanin allon kanban na yau da kullum, da ginshiƙai daga Backlog zuwa An gama, amma wakilan AI ne ke ɗaukar katunan. Suna ba da rahoton ci gaba, suna tambaya idan sun makale, kuma kullum suna jiran yardarku."]},{"n":55,"texts":["AI-gile allon kanban ne inda ƙungiyar ta kunshi wakilan AI. Kowane aiki yana da jagora da ke tsara aikin da masu taimako da ke gina shi. Idan fasali ya shirya, mai gwajin AI yana gwada shi ya ɗauki hoton allo, sannan ya isa tarinku. Ku karɓa, ko ku yi sharhi su sake yi.","Ya fara ne a matsayin hanyar mutum ɗaya na bin zaman rubuta lamba na AI da yawa lokaci guda, sannan ya girma ya zama allo na gaske. Yana aiki a injin ɗinku, ba ya buƙatar asusu, kuma ba shi da masu bin diddigi. Haka kuma ba a gama ba, don haka ku sa ran gefuna masu tsauri da wani abin mamaki.","Ga sigar gaskiya. Har yanzu dole ne ku kasance da ra'ayoyin, kuma dole ne ku duba sakamakon. Abin da AI-gile ke yi shi ne duk abin da ke tsakanin: yana tsara katunan, yana tashe wakilin da ya dace idan kun yi sharhi, yana nuna daidai abin da ya canza, kuma yana tara komai a ɗan gajeren tari a gare ku."]},{"n":89,"texts":["AI-gile allon kanban ne kyauta da kuke gudanarwa a kwamfutarku. Maimakon mutane, kowane aiki yana da ƙungiyar wakilan AI: jagora da ke mayar da ra'ayoyinku kati da shiri, da masu taimako da ke ɗaukar katunan bisa fifiko. Idan an gina wani abu, mai gwajin AI yana bin matakan gwaji ya nuna muku abin da ya gani. Sannan yana jira a tari ɗaya mai suna Gare ku. Kuna karɓa, ko ku yi sharhi ƙungiyar ta sake gwadawa. Babu abin da ke isa An gama ba tare da ku ba.","Akwai wasu siffofi da ba za ku yi tsammani ba. Tsaron dare yana cika ginshiƙin A yi yayin da kuke barci, yana zaɓar katunan da ba sa buƙatar amsarku. Na'urar ƙidayar token tana nuna yawan da wakilai suka yi amfani da shi yau da wannan mako, kuma Yanayin Babu Token yana gaya musu su daina kashewa. Kuna iya aika saƙo ga abokai, kuma saƙonnin sirri an ɓoye su daga ƙarshe zuwa ƙarshe. Allon yana magana da harsuna kusan 120, ciki har da Dutch, Flemish, na 'yan fashin teku da Klingon. Babu ɗaya daga cikinsu da ke da farashi, kuma babu wanda ke ƙoƙarin sayar muku.","AI-gile ƙaramin aiki ne na kai, ba kamfani ba. Rich yana son kula da ayyukan rubuta lamba na AI da yawa ba tare da buɗe kowace manhaja ya duba ba, don haka shi da wakilai suka gina allo don haka, sannan suka yi amfani da allon wajen gina sauran. Yana pre-alpha a rufe, ma'ana yana aiki, galibi, ga ɗimbin abokai. Babu shafin farashi, babu jaridar imel, babu shirin girma. Idan ya yi kama da mai amfani, kuna iya neman gwadawa idan ya buɗe kaɗan."]},{"n":144,"texts":["AI-gile allon kanban ne don mutum ɗaya da wakilan AI da yawa. Yana aiki a kwamfutarku kuma kyauta ne gaba ɗaya. Kuna ƙara ayyuka, kuma kowane aiki yana samun jagora da ƙaramar ƙungiya. Kuna hira da jagora, kamar Discord, kuna kwatanta ra'ayi; jagora yana mayar da shi kati da shiri, sannan yana jiran ku danna Go. Ƙungiyar tana aiki ta cikin katunan bisa fifiko, da layin umarni mai sauƙi da aka yi wa samfuran harshe. Kafin wani abu ya dawo gare ku, mai gwajin AI yana bin matakai a kwafin manhajar ya haɗa hoton allo. Aikin da aka gama yana isa tarinku tare da fayilolin da suka canza da bambancin. Kuna karɓa, ko ku bar sharhi ƙungiyar ta farka ta sake gwadawa. Ku kaɗai ne za ku iya matsar da kati zuwa An gama.","Kwana ɗaya da AI-gile, kusan. Da yamma kuna barin sharhi kaɗan: wannan maɓalli yana wurin da bai dace ba, ya kamata a jera wancan jerin, za mu iya samun yanayin duhu. Kuna kwanciya barci. Wakilai suna karanta sharhin, suna yin sauye-sauyen, suna gwada su, suna mayar muku. Idan A yi ya ƙare, tsaron dare yana cika shi daga backlog da katunan da ba sa buƙatar amsarku. Da safe akwai tari ɗaya gajere: tambayoyi biyu da abubuwan gwadawa kaɗan, kowanne da matakan da mai barci zai iya bi da hoton allo na yana aiki. Kuna danna, kuna karɓar masu kyau, kuna mayar da sauran. Na'urar ƙidayar token tana nuna abin da aka yi amfani da shi, kuma Yanayin Babu Token yana nan don makonni masu sauƙi. Sannan kuna karin kumallo, wanda wakilai ba za su iya taimako a kai ba tukuna.","Da farko, abin da AI-gile ba shi ba. Ba kamfanin farawa ba ne, ba na sayarwa ba, kuma babu wanda ke tattara bayananku. Allo ne kyauta da ke aiki a kwamfutarku, babu asusu, babu masu bin diddigi, babu kuki. Abin da yake shi ne: wuri ɗaya mai tsabta don ganin duk ayyukan rubuta lamba na AI a lokaci guda, da ƙungiyar wakilai suna yin katunan, ku kuma kuna yanke shawara. Yana haɗa katunan masu alaƙa, yana gyara taken da suka ruɗe, kuma yana lura da yadda lamba take zama marar nauyi. Yana magana da harsuna kusan 120, daga Dutch da Flemish zuwa na 'yan fashin teku da Klingon. Abokai za su iya aika wa juna saƙo, a sirri kuma a ɓoye. Rich da wakilai masu haƙuri da yawa ne suka gina shi, galibi suna amfani da shi da kansa. Yana pre-alpha a rufe, don haka akwai tsauri a wurare. Idan ya yi kama da nishaɗi, ku nemi da ladabi kuma wataƙila ku shiga da wuri."]}],"quips":{"1":"Kalma ɗaya. Jarumtaka. Wataƙila ta wuce kima.","3":"Kalmomi uku. Sun fi gaskiya fiye da yawancin shafukan samfura.","8":"Kalmomi takwas. Har yanzu sun fi taro gajarta.","21":"Tsawon kalmomi maki na labari ne, ta hanya. Ai haka ne.","55":"Kalmomi hamsin da biyar. An gama katuna biyu yayin da kuke karanta wannan.","144":"Wannan shi ne dogon. Babu 233. Wakilai sun tafi barci."}},"timeline":{"first-idea.name":"Ra'ayin farko","first-idea.line":"Tattaunawa ta farko, kafin wata lamba ta wanzu.","first-board.name":"Allo na farko","first-board.line":"Allon da ke bin diddigin ginin kansa: katuna, ginshiƙai, ja da sauke, ayyuka.","team-roles.name":"Ƙungiya da matsayi","team-roles.line":"Bayanan wakilai, samfuran ƙungiya, wurare da wanda ke yin me.","install.name":"Shigarwa da fitarwa","install.line":"Zip da aboki zai iya shigarwa, sabuntawa kai-tsaye, hanyoyi da komawa baya.","usage-saver.name":"Tanadin amfani","usage-saver.line":"Auna abin da gudanarwa ke ci, kiyaye lamba marar nauyi, ajiye iyakarku.","friends.name":"Abokai da rabawa","friends.line":"DM na sirri, na'urar isar da saƙo a ɓoye, gayyata, matsayi da ayyukan da aka raba.","languages.name":"Harsuna","languages.line":"Kowane rubutun allo a cikin fayil na harshe, Dutch da Flemish na farko.","ai-tester.name":"Mai gwajin AI","ai-tester.line":"Mai gwaji yana duba kowace miƙawa tukuna kuma yana nuna abin da ya gani.","website.name":"Shafin yanar gizo","website.line":"aigile.lol, gwaji na farko da wannan jerin lokaci.","streaming.name":"Hira da yawo","streaming.line":"Discord, Twitch, OBS, yanayin mai yawo, GIF da emoji.","no-ai.name":"Fitowar babu AI","no-ai.line":"Allo ga masu rubuta lamba babu AI, da allunan jama'a.","night-watch.name":"Tsaron dare","night-watch.line":"Mai tsaro da Scrum Master suna kiyaye ƙungiyoyi a kan aiki yayin da kuke barci.","p-more.name":"Duk sauran","p-more.line":"Ƙananan ra'ayoyi da ke jiran lokacinsu.","p-android.name":"Waya da Android","p-android.line":"Isa allonku daga waya, sannan manhajar Android ta asali.","p-release.name":"Alpha da bayansa","p-release.line":"Alpha a rufe, shafin kai-tsaye, sannan beta.","p-languages.name":"Ƙarin harsuna","p-languages.line":"Harsuna 130, da yanayin nutsewa ga masu koyo.","p-engines.name":"Ƙarin injunan AI","p-engines.line":"Zaɓi Claude, Codex, Gemini, Copilot ko Cursor ga kowane wakili.","p-pro.name":"Aikin ƙwararru","p-pro.line":"Alamomin haɗari, ƙofofin haɗawa, katunan faruwa da shingaye.","p-self.name":"Kula da ku","p-self.line":"Yanayin gajiya, tunatarwar kula da kai da 4:20.","p-servers.name":"Sabobi da girma","p-servers.line":"Saitunan sabar na duniya, matsayi da tsara girma.","p-livestream.name":"Ƙarin yawo","p-livestream.line":"Hirar Twitch, emoji na kai da kallon kai-tsaye na jama'a."},"words":{"button":"📖 Kalmomin sana'a","h":"📖 Bayanin kalmomi","intro":"Kalmomin da za ka gamu da su a AI-gile, da Hausa mai sauƙi: gina shi, canza shi lafiya, ci gaba da sa shi aiki ga mutanen da ke amfani da shi, da aiki tare a matsayin ƙungiya da AI.","search":"Nemo kalma…","none":"Babu kalmar da ta dace da wannan.","close":"Rufe","count":{"one":"kalma {count}","other":"kalmomi {count}"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Gina shi"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Canza shi lafiya"},{"id":"run","name":"🛎️ Gudanar da sabis"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ra'ayoyi da aikin da ba a tsara su ba tukuna. Ba a yin aiki a kan komai a can sai ya koma A yi."},{"id":"sprint","g":"agile","word":"Sprint","text":"Gajeren lokaci na aiki (sau da yawa mako ɗaya ko biyu) da aka amince da adadin katunan da za a gama.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Takaitaccen taro: abin da kowane memba ya yi, abin da zai yi na gaba, da abin da ke hana shi.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Allo mai ginshiƙai (A yi, Ana yi, An gama) inda katuna ke tafiya daga hagu zuwa dama yayin da ake aiki."},{"id":"wip","g":"agile","word":"Iyakar WIP","text":"Aiki a ci gaba: mafi yawan katunan da ginshiƙi zai ɗauka, don ƙungiya ta gama abubuwa kafin ta fara wasu.","also":["WIP"]},{"id":"dod","g":"agile","word":"Ma'anar An gama","text":"Gajeren jerin ƙungiyar na abin da “an gama” ke nufi, kamar an gwada kuma an bayyana, kafin a miƙa maka kati. Tagwayenta, Ma'anar Shirye, tana faɗin lokacin da kati ya isa a fara shi.","also":["Definition of Done","Ma'anar Shirye","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Waiwaye kan yadda ƙungiyar ke aiki, don a amince da abu ɗaya da za a inganta. A AI-gile retro yana ba da shawarar canji a hanyoyin aikin ƙungiyar, kai kuma ka ce Go ko Ba tukuna ba.","also":["retros","retrospective","waiwaye"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Kowa ya taru: kowace ƙungiya tana barin sauran aiki don taimakawa a kan aiki ɗaya na gaggawa har sai an warware shi. Sauran ayyuka suna jira a halin yanzu.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Wanda ke sa aiki ya ci gaba da gudana: yana lura da katunan da suka makale, yana tunatar da ƙungiyoyi, kuma yana tuna maka abin da ke jira. A AI-gile Lead Scrum Master yana yin haka a kowane aiki.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Babban fayil ɗin lamba na aiki da cikakken tarihin commits, yawanci kuma ana adana shi a GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Layin aiki na daban a cikin lamba, don a yi canje-canje ba tare da taɓa babbar sigar ba.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Hoton lamba da aka adana, tare da gajeren bayanin abin da ya canja. Kullum za a iya komawa ɗaya.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Aika hotunan da aka adana (commits) daga wannan kwamfuta zuwa GitHub, don a adana su a raba su."},{"id":"merge","g":"build","word":"Merge","text":"Mayar da canje-canjen branch cikin babbar sigar."},{"id":"pr","g":"build","word":"Pull request","text":"Neman a duba canje-canjen branch a haɗa su cikin babbar sigar.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tsara lamba ba tare da canja abin da take yi ba: ƙananan fayiloli, sunaye masu haske, ƙarancin maimaitawa."},{"id":"bug","g":"build","word":"Bug","text":"Wani abu da ba ya aiki yadda ya kamata.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Bitar abokin aiki","text":"Idanu na biyu: wani AI yana duba aikin kowane kati kafin ya iso gare ka, don kurakurai kaɗan ne kawai su wuce.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Gwaji","text":"Gwada aikin da aka gama don tabbatar yana yin abin da aka nema, kafin a karɓa.","also":["gwada","gwadawa","gwaje-gwaje","gwajin","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Gajeriyar quality assurance (tabbatar da inganci): binciken atomatik da ke gudana kafin wani abu ya fita kai tsaye. Idan QA ja ne, wani abu ya gaza, kuma ba zai fita kai tsaye ba sai an gyara shi.","also":["binciken inganci","quality checks"]},{"id":"testpile","g":"test","word":"Tarin gwaji","text":"Katunan da aka gama da ke jiran ka gwada, ɗaya bayan ɗaya. Karɓi ɗaya ko mayar da shi da bayani, sai na gaba ya bayyana.","also":["test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Sa sabuwar sigar ta fara aiki, misali a sabar da mutane ke amfani da ita."},{"id":"release","g":"change","word":"Sakewa","text":"Tarin aikin da aka gama mai suna wanda ke fita kai tsaye tare, da gajerun bayanai kan abin da ya canza. 🚀 Sakewa na rubuta bayanan daga katunan da aka gama.","also":["sakewa","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Komawa sigar ƙarshe da ke aiki idan sabuwa ta kawo matsala. A AI-gile yana yin jerin matakan mayarwa da aka rubuta a kan kowane canji.","also":["roll back","mayar da baya"]},{"id":"live","g":"change","word":"Kai tsaye","text":"Ainihin sigar da mutane ke amfani da ita, ba kwafi don gwada abubuwa ba. Masu haɓakawa kuma suna kiranta production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Canji","text":"Canjin da aka tsara a kan abin da mutane suka dogara da shi, an rubuta shi tukuna: me, me yasa, haɗarin, yaushe, da yadda za a mayar da shi. Fara ɗaya da 🔀 Gabatar da canji.","also":["canje-canje","buƙatar canji","change request"],"noTip":1},{"id":"risk","g":"change","word":"Haɗari","text":"Wani abu da zai iya lalacewa, an ba shi maki gwargwadon yiwuwarsa da girman illarsa. ⚠️ Haɗura na ajiye su a jeri ɗaya, mafi girman maki a farko, kowanne da ranar sake dubawa.","also":["haɗura","rajistar haɗura","risk register"]},{"id":"chgwin","g":"change","word":"Tagar canji","text":"Lokutan da canje-canje za su iya fita kai tsaye, kamar maraicen Talata mai shiru. A wajen taga ba za a iya gama katin canji ba, sai dai idan gaggawa ce.","also":["tagogin canji","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ƙuri'a cikin sauri kafin canji ya fita kai tsaye: kowane mutum da dole ne ya amince yana cewa Go ko No go. Yana ci gaba ne kawai idan sun yarda.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Amincewa","text":"Jiran “eh” kafin aiki ya fara. Katin da aboki ya gabatar, ko canji, yana jira a ✅ Amincewa har sai ka amince ko ka ƙi.","also":["approval","approvals"]},{"id":"quiettime","g":"change","word":"Lokacin shiru","text":"Wani lokaci, kamar watsa shirye-shirye, nuni ko dare, da babu abin da ke fita kai tsaye. Ƙungiyoyi suna ci gaba da aiki da gwaji, amma fita kai tsaye na jira har ya ƙare. A wasu wurare ana kiransa change freeze.","also":["lokutan shiru","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Sabis","text":"Abin da ka gina da mutane suka dogara da shi, kamar shafin yanar gizo ko manhaja, ana kula da shi don ya ci gaba da aiki. Yi alama a “Wannan aiki sabis ne” ka faɗi abin da yake bayarwa, wa ke amfani da shi da wa ke kan kira.","also":["sabis-sabis","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Binciken uptime","text":"Bincike na atomatik, bayan 'yan mintuna, cewa sabis ɗinka yana amsawa har yanzu. Idan ya gaza sau da yawa a jere, AI-gile zai buɗe katin matsala da kansa.","also":["uptime","binciken aiki"]},{"id":"statuspage","g":"run","word":"Shafin matsayi","text":"Shafin jama'a da ke nuna ko sabis yana aiki (kore, lemu ko ja) tare da sabon bayani, don mutanen da ke amfani da shi su duba maimakon tambaya.","also":["shafukan matsayi","status page"]},{"id":"desk","g":"run","word":"Teburin sabis","text":"Inda tambayoyi da rahotanni daga mutanen da ke amfani da sabis ɗinka ke shigowa. AI-gile yana tsara kowanne zuwa buƙata, matsala ko ra'ayi, kuma yana faɗa idan ya yi kama da wani abu da aka riga aka ruwaito.","also":["teburan sabis","teburin taimako","help desk"]},{"id":"svcrequest","g":"run","word":"Buƙatar sabis","text":"Wani yana neman abu na yau da kullum, kamar sabon asusu ko ɗan taimako, maimakon ya ruwaito cewa wani abu ya lalace. Tana jiran lokacinta; matsala tana zuwa farko.","also":["buƙatun sabis"]},{"id":"incident","g":"run","word":"Matsala","text":"Wani abu da ya lalace ga mutanen da ke amfani da shi a yanzu, kamar shafin yanar gizo ya faɗi. Katin 🔥 matsala yana tsallake layi: sake sa shi aiki shi ne na farko.","also":["matsaloli","incident"]},{"id":"major","g":"run","word":"Babbar matsala","text":"Matsala mai girma sosai: mutane da yawa abin ya shafa, ko kuɗi ko bayanai suna cikin haɗari. Maɓalli ɗaya yana sa dukkan ƙungiyoyi a kanta (swarm), yana tashe duk wanda ke kan kira, kuma yana neman bayanin matsayi kowane mintuna 30.","also":["manyan matsaloli","major incident"]},{"id":"oncall","g":"run","word":"Kan kira","text":"Kasancewa wanda ke amsawa idan wani abu ya lalace, ko da da dare. Kowane sabis yana da memba na ƙungiya a kan kira wanda ake tashe da farko don matsalolinsa.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Lokacin amsa","text":"Tsawon lokacin da kati zai iya jira amsa ta farko, misali awa ɗaya don matsala. Bayan haka yana samun agogo ja, don kada a manta da wani abu shiru. Ana kuma kiransa burin amsa.","also":["lokutan amsa","burin amsa","response target"]},{"id":"postmortem","g":"run","word":"Bita bayan matsala","text":"Ɗan duba baya bayan matsala: abin da ya faru, abin da ya taimaka da abin da za a canza, ba tare da zargin kowa ba. Ba za a iya rufe matsala ba sai da ita.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Matsala mai maimaituwa","text":"Ɓoyayyen dalili a bayan matsala ɗaya ko fiye. Katin 🧩 matsala mai maimaituwa yana tara matsalolin da ke ta dawowa, don a gano dalilin a gyara shi har abada.","also":["problem","matsalar tushe"],"noTip":1},{"id":"rootcause","g":"run","word":"Tushen dalili","text":"Ainihin dalilin da ya sa wani abu ya lalace, ba kawai abin da ka ga ya ɓaci ba. Gyara tushen dalilin, matsalar za ta daina dawowa.","also":["tushen matsala","root cause"]},{"id":"workaround","g":"run","word":"Mafita na ɗan lokaci","text":"Hanyar sa abubuwa su ci gaba da aiki har ainihin gyaran ya shirya, kamar sake kunna wani abu idan ya makale. Ana rubuta ta a katin matsala mai maimaituwa don kada wani ya sake nemo ta.","also":["hanyar wucin gadi","workaround"]},{"id":"knownerror","g":"run","word":"Kuskuren da aka sani","text":"Matsala mai maimaituwa da aka fahimci dalilinta kuma tana da mafita na ɗan lokaci, amma ba a gyara ta ba tukuna. 🧩 Kurakuran da aka sani na jera su, don kowa ya yi amfani da mafitar maimakon sake tona.","also":["kurakuran da aka sani","known error"]},{"id":"runbook","g":"run","word":"Littafin aiki","text":"Umarnin mataki-mataki don gyara wani irin matsalar da aka sani, don a yi ta hanya ɗaya, cikin sauri, kowane lokaci. Bayan babbar matsala ƙungiyar za ta iya ba da shawarar ɗaya don ka ba da OK.","also":["runbook","runbooks"]},{"id":"ci","g":"run","word":"Abin tsari","text":"Abu ɗaya da sabis ɗinka ya dogara a kai, kamar sabar, sunan yanki, takardar shaida, maɓalli ko mai kawowa. 🗂️ Abubuwan tsari na jera su ga kowane sabis, don ka ga abin da matsala take shafa da abin da ke buƙatar sabuntawa ko ajiyar tsaro.","also":["abubuwan tsari","configuration item"]},{"id":"expiry","g":"run","word":"Ranar ƙarewa","text":"AI-gile yana sa ido kan ranaku kamar lokacin da takardar shaida ko sunan yanki zai ƙare. Cikin kwanaki 30 kafin ranar yana ƙirƙirar kati ɗaya don a sabunta shi, don kada wani abu ya daina aiki ba zato ba tsammani.","also":["ranakun ƙarewa","ƙarewa","sa ido kan ƙarewa"]},{"id":"backup","g":"run","word":"Ajiyar tsaro","text":"Kwafin bayananka da aka ajiye tun da, don a koma gare shi idan wani abu ya ɓace ko ya lalace. AI-gile na yin ajiyar tsaro na allunanka kowace rana.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Maido","text":"Mayar da bayanai daga ajiyar tsaro. Ajiyar tsaro tana da amfani da gaske ne kawai idan ka san za a iya maido ta, don haka yana da kyau a gwada lokaci-lokaci.","also":["maidowa","restore"]},{"id":"svcreview","g":"run","word":"Bitar sabis","text":"Waiwaye kan wata ɗaya na sabis: matsalolin da aka buɗe da aka gyara, yadda mutane suka sami amsa da sauri, uptime da tokens da aka yi amfani da su. Bitar wata tana nuna shi ga kowane sabis.","also":["bitocin sabis","bitar wata","bitocin wata"]},{"id":"accessreview","g":"run","word":"Duba samun dama","text":"Duba kowane kwanaki 90 wanda har yanzu zai iya shiga: hanyoyin rabawa, matsayin abokai da sirrikan da aka ajiye. Kana ajiyewa ko cire kowanne, don kada tsohuwar damar shiga ta daɗe.","also":["binciken samun dama","access review"]},{"id":"improvements","g":"run","word":"Jerin ingantawa","text":"Duk abin da ƙungiyar ta yanke shawarar ingantawa, a wuri ɗaya: shawarwarin retro, ayyukan bita da gyaran matsaloli, kowanne da matsayinsa. Za ka same shi a ƙarƙashin 📈 Ingantawa.","also":["jerin ingantawa","ingantawa"]},{"id":"tokencap","g":"run","word":"Iyakar tokens","text":"Iyakar wata-wata kan tokens da wakilan sabis za su iya amfani da su. A 80% za ka sami gargaɗi; a 100% aikinsu na bayan fage yana jira har wata mai zuwa ko har sai ka ɗaga iyakar.","also":["iyakokin tokens","token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Wakili","text":"AI da ke aiki shi kaɗai a kan aiki: yana karanta lamba, yana yin canje-canje, yana gudanar da bincike, yana ba da rahoto.","also":["agents","wakilai","agent"]},{"id":"token","g":"ai","word":"Token","text":"Ma'aunin da ake ƙirga amfanin AI da shi: kusan ƴan haruffa na rubutu da aka karanta ko aka rubuta. Ƙarancin token, ƙarin tsarinku ya rage.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Ƙaramin umarni da ke gudana da kansa a lokaci da aka tsara, misali lokacin da zaman AI ya fara, don ƙungiya ta ji sharhinku.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
